'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'

export default function DesafiosPage() {
  const [desafios, setDesafios] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [mostrarForm, setMostrarForm] = useState(false)
  const [desafioSeleccionado, setDesafioSeleccionado] = useState<any>(null)
  const [form, setForm] = useState({
    nombre: '',
    telefono: '',
  })
  const supabase = createClient()

  useEffect(() => {
    cargarDesafios()
  }, [])

  const cargarDesafios = async () => {
    const { data } = await supabase
      .from('desafios')
      .select('*, canchas(nombre, tipo, precio_hora), complejos(nombre)')
      .eq('estado', 'abierto')
      .order('fecha', { ascending: true })

    setDesafios(data || [])
    setLoading(false)
  }

  const aceptarDesafio = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!desafioSeleccionado) return

    const monto_seña = desafioSeleccionado.canchas.precio_hora / 2

    await supabase.from('reservas').insert({
      cancha_id: desafioSeleccionado.cancha_id,
      complejo_id: desafioSeleccionado.complejo_id,
      fecha: desafioSeleccionado.fecha,
      hora_inicio: desafioSeleccionado.hora_inicio,
      hora_fin: desafioSeleccionado.hora_fin,
      cliente_nombre: form.nombre,
      cliente_telefono: form.telefono,
      monto_seña,
      monto_total: desafioSeleccionado.canchas.precio_hora,
      metodo_pago: 'transferencia',
      estado: 'pendiente',
      es_desafio: true,
      desafio_id: desafioSeleccionado.id,
    })

    await supabase
      .from('desafios')
      .update({ estado: 'completo' })
      .eq('id', desafioSeleccionado.id)

    alert('¡Desafío aceptado! Te contactaremos para confirmar.')
    setMostrarForm(false)
    setDesafioSeleccionado(null)
    cargarDesafios()
  }

  const tipoLabel: Record<string, string> = {
    futbol_5: '⚽ Fútbol 5',
    futbol_7: '⚽ Fútbol 7',
    futbol_11: '⚽ Fútbol 11',
    paddle: '🎾 Pádel',
  }

  return (
    <main className="min-h-screen bg-gradient-to-b from-green-50 to-white">
      <nav className="bg-white shadow-sm px-6 py-4 flex justify-between items-center">
        <h1 className="text-xl font-bold text-green-700">⚔️ Desafíos disponibles</h1>
        <a href="/" className="text-green-600 hover:underline text-sm">← Volver al inicio</a>
      </nav>

      <div className="container mx-auto px-4 py-8 max-w-3xl">
        <div className="mb-8">
          <h2 className="text-2xl font-bold text-gray-800 mb-2">🎯 Encontrá tu próximo partido</h2>
          <p className="text-gray-500">Aceptá un desafío y pagá solo tu mitad de la seña</p>
        </div>

        {loading ? (
          <div className="text-center text-gray-400 py-10">Cargando desafíos...</div>
        ) : desafios.length === 0 ? (
          <div className="bg-white rounded-xl shadow-sm p-10 text-center text-gray-400">
            <p className="text-4xl mb-3">⚔️</p>
            <p className="font-medium">No hay desafíos disponibles en este momento</p>
            <p className="text-sm mt-1">Volvé más tarde o creá tu propio desafío</p>
          </div>
        ) : (
          <div className="space-y-4">
            {desafios.map((desafio) => (
              <div key={desafio.id} className="bg-white rounded-xl shadow-sm p-6 border border-gray-100">
                <div className="flex justify-between items-start">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2">
                      <h3 className="font-bold text-gray-800">{desafio.equipo_creador_nombre}</h3>
                      <span className="text-xs px-2 py-1 rounded-full bg-green-100 text-green-700 font-medium">
                        Busca {desafio.jugadores_necesarios} jugadores
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 mb-2">
                      🏟️ {desafio.complejos.nombre} · {desafio.canchas.nombre}
                    </p>
                    <p className="text-sm text-gray-600 mb-2">
                      📅 {desafio.fecha} · ⏰ {desafio.hora_inicio} - {desafio.hora_fin}
                    </p>
                    <p className="text-sm text-gray-500">
                      {tipoLabel[desafio.canchas.tipo]}
                    </p>
                    <p className="text-green-600 font-semibold mt-2">
                      💰 Tu parte: ${(desafio.canchas.precio_hora / 2).toLocaleString()}
                    </p>
                  </div>
                  <button
                    onClick={() => { setDesafioSeleccionado(desafio); setMostrarForm(true) }}
                    className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 transition font-medium"
                  >
                    ⚔️ Aceptar
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Modal para aceptar desafío */}
        {mostrarForm && desafioSeleccionado && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl p-6 max-w-md w-full">
              <h3 className="text-xl font-bold text-gray-800 mb-4">⚔️ Aceptar desafío</h3>
              <form onSubmit={aceptarDesafio} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Nombre de tu equipo</label>
                  <input
                    type="text"
                    value={form.nombre}
                    onChange={(e) => setForm({ ...form, nombre: e.target.value })}
                    required
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-green-500"
                    placeholder="Los Cracks FC"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">WhatsApp</label>
                  <input
                    type="text"
                    value={form.telefono}
                    onChange={(e) => setForm({ ...form, telefono: e.target.value })}
                    required
                    className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-green-500"
                    placeholder="1123456789"
                  />
                </div>
                <div className="bg-green-50 border border-green-200 rounded-lg p-3 text-sm">
                  <p className="text-green-700 font-medium">💰 Vas a pagar: ${(desafioSeleccionado.canchas.precio_hora / 2).toLocaleString()}</p>
                  <p className="text-green-600 text-xs mt-1">Transferí y enviá el comprobante por WhatsApp</p>
                </div>
                <div className="flex gap-3">
                  <button
                    type="submit"
                    className="flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition font-medium"
                  >
                    Confirmar
                  </button>
                  <button
                    type="button"
                    onClick={() => { setMostrarForm(false); setDesafioSeleccionado(null) }}
                    className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition"
                  >
                    Cancelar
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </main>
  )
}